MAKE CODE: Stepper A4988 Loop
#include <AccelStepper.h>

const int stepPin = 3;
const int dirPin = 2;
const int enablePin = 10;
const long stepsPerTurn = 200L * 8; // 1.8 degree motor, 1/8 microstepping

AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

void setup() {
  pinMode(enablePin, OUTPUT);
  digitalWrite(enablePin, LOW); // Enable driver
  stepper.setMaxSpeed(2000);    // Steps per second
  stepper.setAcceleration(1000); // Steps per second per second
  stepper.moveTo(stepsPerTurn);
}

void loop() {
  if (stepper.distanceToGo() == 0) {
    stepper.moveTo(-stepper.currentPosition()); // Reverse direction
  }
  stepper.run();
}
END
